package main

import (
    "fmt"
    "os"
    "path/filepath"
    "sort"
    "strings"
)

const version = "2.37.1"

type App struct {
    Env Env
    Self string
    Cwd string
    Config *Config
    Log Logger
}

type exitError struct{ code int }
func (e exitError) Error() string { return fmt.Sprintf("exit status %d", e.code) }

func main() {
    cwd, _ := os.Getwd()
    self, err := os.Executable()
    if err != nil { self, _ = filepath.Abs(os.Args[0]) }
    a := &App{Env: getEnv(), Self: self, Cwd: cwd, Log: defaultLogger()}
    if err := a.run(os.Args[1:]); err != nil {
        if e, ok := err.(exitError); ok { os.Exit(e.code) }
        a.Log.Error("error %s", err)
        os.Exit(1)
    }
}

func first(args []string) string { if len(args)>0 { return args[0] }; return "" }
func at(args []string, n int, fallback string) string { if len(args)>n { return args[n] }; return fallback }

func (a *App) run(args []string) error {
    name := first(args)
    if len(args)>0 { args=args[1:] }
    switch name {
    case "", "--help": name="help"
    case "--version": name="version"
    case "permit", "grant": name="allow"
    case "deny", "disallow", "revoke": name="block"
    }
    switch name {
    case "allow", "block", "edit", "exec", "export", "prune", "reload", "status", "stdlib", "log", "check-required":
        c, err := a.loadConfig()
        if err != nil { return err }
        a.Config=c
    }
    switch name {
    case "help": a.help(len(args)>0); return nil
    case "version": return a.version(args)
    case "hook": return a.hook(first(args))
    case "stdlib": fmt.Print(a.stdlib()); return nil
    case "log":
        if len(args)!=2 { return fmt.Errorf("invalid arguments") }
        switch args[0] {
        case "--status": a.Log.Status(args[1])
        case "--error": a.Log.Error(args[1])
        default: return fmt.Errorf("invalid log-type '%s'", args[0])
        }
        return nil
    case "status": return a.status(args)
    case "allow", "block": return a.authorize(first(args),name=="allow")
    case "prune": return a.prune()
    case "reload": return a.reload()
    case "export": return a.export(first(args))
    case "exec": return a.exec(args)
    case "edit": return a.edit(args)
    case "dump": return a.dump(args)
    case "show_dump": return a.showDump(args)
    case "apply_dump": return a.applyDump(args)
    case "dotenv": return a.dotenv(args)
    case "watch": return a.watch(args)
    case "watch-dir": return a.watchDir(args)
    case "watch-list": return a.watchList(args)
    case "watch-print": return a.watchPrint(args)
    case "current": return a.current(args)
    case "check-required": return a.checkRequired(args)
    case "fetchurl": return a.fetchURL(args)
    default: return fmt.Errorf("command %q not found",strings.Join(os.Args," "))
    }
}

var shellNames = []string{"bash","elvish","fish","gha","gzenv","json","murex","pwsh","tcsh","vim","zsh","systemd"}
func validShell(s string) bool { for _,n:=range shellNames { if s==n {return true} };return false }
func checkShell(s string) error { if !validShell(s) { return fmt.Errorf("unknown target shell '%s'",s) };return nil }

func (a *App) help(private bool) {
    fmt.Printf("direnv v%s\nUsage: direnv COMMAND [...ARGS]\n\nAvailable commands\n------------------\n",version)
    fmt.Print("allow [PATH_TO_RC]:\n  aliases: permit, grant\n  Grants direnv permission to load the given .envrc or .env file.\n")
    if private {fmt.Print("*apply_dump FILE:\n  Accepts a filename containing `direnv dump` output and generates a series of bash export statements to apply the given env\n*show_dump DUMP:\n  Show the data inside of a dump for debugging purposes\n*check-required SHELL ENVRC_PATH PATH...:\n  Checks if required files have been allowed\n")}
    fmt.Print("block [PATH_TO_RC]:\n  aliases: deny, disallow, revoke\n  Revokes the authorization of a given .envrc or .env file.\n")
    if private {fmt.Print("*dotenv [SHELL] [PATH_TO_DOTENV]:\n  Transforms a .env file to evaluatable `export KEY=PAIR` statements\n*dump [SHELL] [FILE]:\n  Used to export the inner bash state at the end of execution\n")}
    fmt.Print("edit [PATH_TO_RC]:\n  Opens PATH_TO_RC or the current .envrc or .env into an $EDITOR and allow\n  the file to be loaded afterwards.\nexec DIR COMMAND [...ARGS]:\n  Executes a command after loading the first .envrc or .env found in DIR\nexport SHELL:\n  Loads an .envrc or .env and prints the diff in terms of exports.\n")
    fmt.Printf("  Supported SHELL values are: [%s]\n",strings.Join(shellNames,", "))
    fmt.Print("fetchurl <url> [<integrity-hash>]:\n  Fetches a given URL into direnv's CAS\nhelp [SHOW_PRIVATE]:\n  Shows this help\nhook SHELL:\n  Used to setup the shell hook\nprune:\n  Removes old allowed and required files\nreload:\n  Triggers an env reload\nstatus [--json]:\n  Prints some debug status information\nstdlib:\n  Displays the stdlib available in the .envrc execution context\nversion [VERSION_AT_LEAST]:\n  prints the version or checks that direnv is older than VERSION_AT_LEAST.\n")
    if private {fmt.Print("*watch SHELL PATH...:\n  Adds a path to the list that direnv watches for changes\n*watch-dir SHELL DIR:\n  Recursively adds a directory to the list that direnv watches for changes\n*watch-list [SHELL]:\n  Pipe pairs of `mtime path` to stdin to build a list of files to watch.\n*watch-print [--null]:\n  prints the watched paths\n*current PATH:\n  Reports whether direnv's view of a file is current (or stale)\n")}
    fmt.Print("log [--status | --error] <message>:\n  Logs a given message\n")
    if private {fmt.Println("* = private commands")}
}

func sortedKeys[V any](m map[string]V) []string {
    keys:=make([]string,0,len(m));for k:=range m {keys=append(keys,k)};sort.Strings(keys);return keys
}
EOF
cat > env.go <<'EOF'
package main

import (
    "bytes"
    "compress/zlib"
    "encoding/base64"
    "encoding/json"
    "fmt"
    "io"
    "os"
    "strings"
)

type Env map[string]string
type Patch map[string]*string

type Diff struct {
    Prev Env `json:"p"`
    Next Env `json:"n"`
}

func getEnv() Env {
    e:=Env{}
    for _,s:=range os.Environ() {k,v,ok:=strings.Cut(s,"=");if ok {e[k]=v}}
    return e
}
func (e Env) clone() Env {n:=Env{};for k,v:=range e {n[k]=v};return n}
func (e Env) list() []string {out:=make([]string,0,len(e));for k,v:=range e {out=append(out,k+"="+v)};return out}
func pointer(s string) *string {return &s}
func ignoredKey(k string) bool {
    switch k {case "PWD","OLDPWD","SHLVL","_","SHELL","PS1","PS2","PS3","PS4","DIRENV_IN_ENVRC": return true}
    return strings.HasPrefix(k,"BASH_FUNC_")
}
func difference(prev, next Env) Diff {
    d:=Diff{Env{},Env{}}
    for k,v:=range prev {if ignoredKey(k) {continue};if w,ok:=next[k]; !ok || v!=w {d.Prev[k]=v}}
    for k,v:=range next {if ignoredKey(k) {continue};if w,ok:=prev[k]; !ok || v!=w {d.Next[k]=v}}
    return d
}
func (d Diff) patch() Patch {
    p:=Patch{}
    for k:=range d.Prev {p[k]=nil}
    for k,v:=range d.Next {p[k]=pointer(v)}
    return p
}
func (d Diff) reverse(e Env) Env {
    n:=e.clone()
    for k:=range d.Next {delete(n,k)}
    for k,v:=range d.Prev {n[k]=v}
    return n
}
func fullPatch(e Env) Patch {p:=Patch{};for k,v:=range e {p[k]=pointer(v)};return p}

func marshal(v any) (string,error) {
