type Logger struct {
    Format string
    ErrorFormat string
    Filter *regexp.Regexp
}
func defaultLogger() Logger {return Logger{"\x1b[0mdirenv: %s","\x1b[31mdirenv: %s\x1b[0m",nil}}
func (l Logger) Status(s string,args ...any) {
    if l.Format=="" {return}
    msg:=fmt.Sprintf(fmt.Sprintf(l.Format,s),args...)
    if l.Filter!=nil && l.Filter.MatchString(msg) {return}
    fmt.Fprintln(os.Stderr,msg)
}
func (l Logger) Error(s string,args ...any) {
    fmt.Fprintf(os.Stderr,fmt.Sprintf(l.ErrorFormat,s)+"\n",args...)
}

type Config struct {
    ConfigDir string
    DataDir string
    CacheDir string
    Bash string
    LoadDotenv bool
    StrictEnv bool
    DisableStdin bool
    HideEnvDiff bool
    WarnTimeout time.Duration
