}
func (a *App) configDirectory() string {
    if s:=a.Env["DIRENV_CONFIG"];s!="" {return s}
    if s:=a.Env["XDG_CONFIG_HOME"];s!="" {return filepath.Join(s,"direnv")}
    if s:=a.Env["HOME"];s!="" {return filepath.Join(s,".config","direnv")}
    return ""
}
func (a *App) dataDirectory() string {
    if s:=a.Env["XDG_DATA_HOME"];s!="" {return filepath.Join(s,"direnv")}
    return filepath.Join(a.Env["HOME"],".local","share","direnv")
}
func (a *App) cacheDirectory() string {
    if s:=a.Env["XDG_CACHE_HOME"];s!="" {return filepath.Join(s,"direnv")}
