}
func (a *App) loadConfig() (*Config,error) {
    c:=&Config{ConfigDir:a.configDirectory(),DataDir:a.dataDirectory(),CacheDir:a.cacheDirectory(),WarnTimeout:5*time.Second,Prefix:[]string{},Exact:map[string]bool{}}
    if c.ConfigDir=="" {return nil,fmt.Errorf("couldn't find a configuration directory for direnv")}
    c.Bash=a.Env["DIRENV_BASH"]
    if c.Bash=="" {
        var err error
        c.Bash,err=exec.LookPath("bash")
        if err!=nil {return nil,fmt.Errorf("can't find bash: %w",err)}
        if abs,err:=filepath.Abs(c.Bash);err==nil{c.Bash=abs}
    }
    if s,ok:=a.Env["DIRENV_WARN_TIMEOUT"];ok && s!="" {
        d,err:=time.ParseDuration(s)
        if err!=nil {a.Log.Error("invalid DIRENV_WARN_TIMEOUT: %s",err)} else {c.WarnTimeout=d}
    }
    filename:=filepath.Join(c.ConfigDir,"direnv.toml")
    b,err:=os.ReadFile(filename)
    if os.IsNotExist(err) {return c,nil}
    if err!=nil {return nil,err}
    values,err:=parseConfigText(string(b))
    if err!=nil{return nil,fmt.Errorf("LoadConfig() failed to parse %s: %w",filename,err)}
    format:="direnv: %s"
    filter:=""
    for _,v:=range values {
        key:=v.key
        tomlErr:=func(msg string) (*Config,error) {return nil,fmt.Errorf("LoadConfig() failed to parse %s: toml: line %d (last key %q): %s",filename,v.line,key,msg)}
        boolPtr:=func(p *bool) error {if b,ok:=v.value.(bool);ok {*p=b;return nil};return fmt.Errorf("incompatible types: TOML value has type %s; destination has type boolean",tomlType(v.value))}
        var e error
        switch key {
        case "global.bash_path":
            s,ok:=v.value.(string);if !ok {return tomlErr("incompatible types: TOML value has type "+tomlType(v.value)+"; destination has type string")};if s!=""{c.Bash=s}
        case "global.disable_stdin":e=boolPtr(&c.DisableStdin)
        case "global.load_dotenv":e=boolPtr(&c.LoadDotenv)
        case "global.strict_env":e=boolPtr(&c.StrictEnv)
        case "global.hide_env_diff":e=boolPtr(&c.HideEnvDiff)
        case "global.warn_timeout":
            d,e2:=time.ParseDuration(fmt.Sprint(v.value));if e2!=nil{return tomlErr(e2.Error())};c.WarnTimeout=d
        case "global.log_format":if s,ok:=v.value.(string);ok {if s!="" {format=s}} else {e=fmt.Errorf("incompatible types: TOML value has type %s; destination has type string",tomlType(v.value))}
        case "global.log_filter":if s,ok:=v.value.(string);ok {filter=s} else {e=fmt.Errorf("incompatible types: TOML value has type %s; destination has type string",tomlType(v.value))}
        case "whitelist.prefix", "whitelist.exact":
            arr,ok:=v.value.([]any);if !ok{return tomlErr("incompatible types: TOML value has type "+tomlType(v.value)+"; destination has type slice")}
            for _,part:=range arr {
                s,ok:=part.(string);if !ok{return tomlErr("incompatible types: TOML value has type "+tomlType(part)+"; destination has type string")}
