    if s,ok:=a.Env["DIRENV_LOG_FORMAT"];ok {format=s}
    if s,ok:=a.Env["DIRENV_LOG_FILTER"];ok {filter=s}
    l:=Logger{Format:format,ErrorFormat:"direnv: %s"}
    if filter!="" {re,e:=regexp.Compile(filter);if e!=nil{return nil,fmt.Errorf("error in log filter: %w",e)};l.Filter=re}
