func expandHome(p,home string) string {if p=="~" {return home};if strings.HasPrefix(p,"~/") {return home+p[1:]};return p}

type configValue struct{key string;value any;line int}
func tomlType(v any) string {switch v.(type) {case string:return "string";case bool:return "bool";case int64:return "int64";case float64:return "float64";case []any:return "[]any"};return "unknown"}
func uncomment(s string) string {
    var q byte
    for i:=0;i<len(s);i++ {ch:=s[i];if q!=0 {if ch=='\\' && q=='"' {i++;continue};if ch==q {q=0};continue};if ch=='"'||ch=='\'' {q=ch};if ch=='#' {return s[:i]}}
    return s
}
func parseConfigText(text string) ([]configValue,error) {
    var out []configValue
    section:=""
    scanner:=bufio.NewScanner(strings.NewReader(text))
    seen:=map[string]bool{}
    line:=0
    for scanner.Scan() {
        line++
        s:=strings.TrimSpace(uncomment(scanner.Text()))
        if s=="" {continue}
        if strings.HasPrefix(s,"[") {
            if !strings.HasSuffix(s,"]") {return nil,fmt.Errorf("toml: line %d: unexpected EOF; expected table name",line)}
            section=strings.TrimSpace(strings.TrimSuffix(s[1:],"]"));continue
        }
        k,value,ok:=strings.Cut(s,"=")
        if !ok {return nil,fmt.Errorf("toml: line %d: unexpected EOF; expected key separator '='",line)}
        k=strings.TrimSpace(k);value=strings.TrimSpace(value)
        key:=k;if section!="" {key=section+"."+k}
        if seen[key] {return nil,fmt.Errorf("toml: line %d (last key %q): Key '%s' has already been defined.",line,key,key)}
        seen[key]=true
        firstLine:=line
        for strings.HasPrefix(value,"[") && !strings.HasSuffix(value,"]") && scanner.Scan() {line++;value+=" "+strings.TrimSpace(uncomment(scanner.Text()))}
        v,err:=parseTomlValue(value)
        if err!=nil {return nil,fmt.Errorf("toml: line %d (last key %q): %w",firstLine,key,err)}
        out=append(out,configValue{key,v,firstLine})
    }
    return out,scanner.Err()
}
func parseTomlValue(s string) (any,error) {
    s=strings.TrimSpace(s)
    if s=="true" {return true,nil};if s=="false" {return false,nil}
    if strings.HasPrefix(s,"\"") {
        v,e:=strconv.Unquote(s);if e!=nil{return nil,fmt.Errorf("invalid string: %s",s)};return v,nil
    }
    if strings.HasPrefix(s,"'") && strings.HasSuffix(s,"'") && len(s)>=2{return s[1:len(s)-1],nil}
    if strings.HasPrefix(s,"[") && strings.HasSuffix(s,"]") {
        body:=s[1:len(s)-1];arr:=[]any{};start:=0;var q byte;depth:=0
        for i:=0;i<=len(body);i++ {
            var ch byte;if i<len(body){ch=body[i]}
            if q!=0 {if ch=='\\' && q=='"'{i++;continue};if ch==q{q=0};continue}
            if ch=='"'||ch=='\''{q=ch;continue};if ch=='['{depth++};if ch==']'{depth--}
            if (ch==',' && depth==0) || i==len(body) {part:=strings.TrimSpace(body[start:i]);start=i+1;if part!=""{v,err:=parseTomlValue(part);if err!=nil{return nil,err};arr=append(arr,v)}}
        }
        return arr,nil
    }
    if i,e:=strconv.ParseInt(strings.ReplaceAll(s,"_",""),10,64);e==nil{return i,nil}
    if f,e:=strconv.ParseFloat(strings.ReplaceAll(s,"_",""),64);e==nil{return f,nil}
    return nil,fmt.Errorf("expected value but found %q instead",s)
}
EOF
