package main

import (
    "fmt"
    "regexp"
    "strconv"
    "strings"
)

var semverRE=regexp.MustCompile(`^v(0|[1-9][0-9]*)(?:\.(0|[1-9][0-9]*))?(?:\.(0|[1-9][0-9]*))?(?:-([0-9A-Za-z.-]+))?(?:\+([0-9A-Za-z.-]+))?$`)
func (a *App) version(args []string) error {
    if len(args)==0 {fmt.Println(version);return nil}
    v:=args[0];if !strings.HasPrefix(v,"v") {v="v"+v}
    m:=semverRE.FindStringSubmatch(v)
    valid:=m!=nil
    if valid && (m[4]!=""||m[5]!="") && m[3]=="" {valid=false}
    if valid {for _,part:=range strings.Split(m[4],".") {if m[4]!="" && part=="" {valid=false};if len(part)>1 && part[0]=='0' {if _,e:=strconv.ParseUint(part,10,64);e==nil{valid=false}}};for _,part:=range strings.Split(m[5],"."){if m[5]!=""&&part==""{valid=false}}}
    if !valid{return fmt.Errorf("%s is not a valid semver version",v)}
    current:=[3]int{2,37,1}
    older:=false
    for i:=0;i<3;i++ {
        n,_:=strconv.ParseUint(m[i+1],10,64)
        if uint64(current[i])<n {older=true;break};if uint64(current[i])>n {break}
    }
    if older {return fmt.Errorf("current version v%s is older than the desired version %s",version,v)}
    return nil
}
EOF

