func bashQuote(s string) string {
    if s=="" {return "''"}
    safe:=true
    for _,c:=range []byte(s) {if !(c>='A'&&c<='Z'||c>='0'&&c<='9'||strings.ContainsRune(",-./@_",rune(c))) {safe=false;break}}
    if safe {return s}
    var b strings.Builder;b.WriteString("$'")
    for _,c:=range []byte(s) {
        switch c {
        case '\'':b.WriteString("\\'")
        case '\\':b.WriteString("\\\\")
        case '\n':b.WriteString("\\n")
        case '\r':b.WriteString("\\r")
        case '\t':b.WriteString("\\t")
        default:if c<32||c>126 {fmt.Fprintf(&b,"\\x%02x",c)} else {b.WriteByte(c)}
        }
    }
    b.WriteByte('\'');return b.String()
}
// A POSIX-safe quotation used when constructing our own bash invocations.
func shQuote(s string) string {return "'"+strings.ReplaceAll(s,"'","'\\''")+"'"}
func fishQuote(s string) string {
    var b strings.Builder;b.WriteByte('\'')
    for _,c:=range []byte(s) {
        switch c {
        case '\'':b.WriteString("\\'")
        case '\\':b.WriteString("\\\\")
        case '\n':b.WriteString("'\\n'")
        case '\r':b.WriteString("'\\r'")
        case '\t':b.WriteString("'\\t'")
        default:if c<32||c>126 {fmt.Fprintf(&b,"'\\X%02x'",c)} else {b.WriteByte(c)}
        }
    }
    b.WriteByte('\'');return b.String()
}
func tcshQuote(s string) string {
    if s==""{return "''"}
    var b strings.Builder
    for _,c:=range []byte(s) {
        switch c {
        case '\'','\\',' ':b.WriteByte('\\');b.WriteByte(c)
        case '\n':b.WriteString("\\n")
        case '\r':b.WriteString("\\r")
        case '\t':b.WriteString("\\t")
        default:
            if c<32||c>126 {fmt.Fprintf(&b,"\\x%02x",c)} else if strings.ContainsRune("!\"#$%&()*+:;<=>?[{|}~",rune(c)) {b.WriteByte('"');b.WriteByte(c);b.WriteByte('"')} else {b.WriteByte(c)}
        }
    }
    return b.String()
}
func singleQuote(s string) string {return "'"+strings.ReplaceAll(s,"'","''")+"'"}
func vimQuote(s string) string {return singleQuote(strings.ReplaceAll(s,"\n","\\n"))}
var envKey=regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

func render(shell string, p Patch) (string,error) {
    switch shell {
    case "json":b,e:=json.MarshalIndent(p,"","  ");return string(b),e
    case "murex","elvish":b,e:=json.Marshal(p);return string(b)+"\n",e
    case "gzenv":return marshal(p)
    }
    var b strings.Builder
    for k,v:=range p {
        switch shell {
        case "bash","zsh":
            if v==nil {fmt.Fprintf(&b,"unset %s;",bashQuote(k))} else {fmt.Fprintf(&b,"export %s=%s;",bashQuote(k),bashQuote(*v))}
        case "fish":
            if v==nil {fmt.Fprintf(&b,"set -e -g %s;",fishQuote(k))} else if k=="PATH" {
                b.WriteString("set -x -g PATH")
                for _,s:=range strings.Split(*v,":") {b.WriteByte(' ');b.WriteString(fishQuote(s))};b.WriteByte(';')
            } else {fmt.Fprintf(&b,"set -x -g %s %s;",fishQuote(k),fishQuote(*v))}
        case "tcsh":
