                b.WriteString("set path = (")
                for _,s:=range strings.Split(*v,":") {b.WriteByte(' ');b.WriteString(tcshQuote(s))};b.WriteString(" );")
            } else {fmt.Fprintf(&b,"setenv %s %s ;",tcshQuote(k),tcshQuote(*v))}
        case "pwsh":
            if v==nil {fmt.Fprintf(&b,"Remove-Item -LiteralPath %s;",singleQuote("env:/"+k))} else {
                key:=strings.ReplaceAll(strings.ReplaceAll(k,"`","``"),"}","`}")
                fmt.Fprintf(&b,"${env:%s}=%s;",key,singleQuote(*v))
            }
        case "vim":
            value:="v:null";if v!=nil{value=vimQuote(*v)}
            fmt.Fprintf(&b,"call setenv(%s,%s)\n",vimQuote(k),value)
        case "systemd":
