var envKey=regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

func render(shell string, p Patch) (string,error) {
    switch shell {
    case "json":b,e:=json.MarshalIndent(p,"","  ");return string(b),e
    case "murex","elvish":b,e:=json.Marshal(p);return string(b)+"\n",e
    case "gzenv":return marshal(p)
    }
    var b strings.Builder
    for k,v:=range p {
        switch shell {
        case "bash","zsh":
            if v==nil {fmt.Fprintf(&b,"unset %s;",bashQuote(k))} else {fmt.Fprintf(&b,"export %s=%s;",bashQuote(k),bashQuote(*v))}
        case "fish":
            if v==nil {fmt.Fprintf(&b,"set -e -g %s;",fishQuote(k))} else if k=="PATH" {
                b.WriteString("set -x -g PATH")
                for _,s:=range strings.Split(*v,":") {b.WriteByte(' ');b.WriteString(fishQuote(s))};b.WriteByte(';')
            } else {fmt.Fprintf(&b,"set -x -g %s %s;",fishQuote(k),fishQuote(*v))}
        case "tcsh":
            if v==nil {fmt.Fprintf(&b,"unsetenv %s ;",tcshQuote(k))} else if k=="PATH" {
                b.WriteString("set path = (")
                for _,s:=range strings.Split(*v,":") {b.WriteByte(' ');b.WriteString(tcshQuote(s))};b.WriteString(" );")
            } else {fmt.Fprintf(&b,"setenv %s %s ;",tcshQuote(k),tcshQuote(*v))}
        case "pwsh":
            if v==nil {fmt.Fprintf(&b,"Remove-Item -LiteralPath %s;",singleQuote("env:/"+k))} else {
                key:=strings.ReplaceAll(strings.ReplaceAll(k,"`","``"),"}","`}")
                fmt.Fprintf(&b,"${env:%s}=%s;",key,singleQuote(*v))
            }
        case "vim":
            value:="v:null";if v!=nil{value=vimQuote(*v)}
            fmt.Fprintf(&b,"call setenv(%s,%s)\n",vimQuote(k),value)
        case "systemd":
            if v!=nil {
                value:=*v
                if strings.ContainsAny(value,"\n'\"\\") {value="\""+strings.ReplaceAll(value,"\"","\\\"")+"\""}
                fmt.Fprintf(&b,"%s=%s\n",k,value)
            }
        case "gha":
            if !envKey.MatchString(k) {fmt.Fprintf(os.Stderr,"direnv: Skipping invalid environment variable key: %s\n",k);continue}
            var id [16]byte;_,_=rand.Read(id[:]);delimiter:="ghadelimiter_"+hex.EncodeToString(id[:])
            value:="";if v!=nil {value=*v}
            fmt.Fprintf(&b,"%s<<%s\n%s\n%s\n",k,delimiter,value,delimiter)
        default:return "",fmt.Errorf("unknown target shell '%s'",shell)
        }
    }
    return b.String(),nil
}
EOF
