    w,err:=watchesFrom(a.Env);if err!=nil{return err}
    scanner:=bufio.NewScanner(os.Stdin)
    line:=0
    for scanner.Scan() {
        line++
        s:=scanner.Text();mt,p,ok:=strings.Cut(s," ")
        if !ok {return fmt.Errorf("line %d: expected to contain two elements",line)}
        t,err:=strconv.Atoi(mt);if err!=nil{return fmt.Errorf("line %d: %w",line,err)}
        w.put(Watch{absolute(p),int64(t),true})
    }
