package main

import (
    "fmt"
    "os"
    "regexp"
    "strings"
    "unicode"
)

var assignmentRE=regexp.MustCompile(`^(?:export\s+)?([A-Za-z0-9_.]+)\s*(?:=\s*|:\s+)(.*)$`)
func parseDotenv(data []byte,env Env) (Env,error) {
    result:=Env{}
    lines:=strings.Split(strings.ReplaceAll(string(data),"\r\n","\n"),"\n")
    lookup:=func(name string) string {
        name,def,ok:=strings.Cut(name,":-")
        v,present:=result[name];if !present {v=env[name]}
        if ok && v=="" {return def};return v
    }
    for i:=0;i<len(lines);i++ {
        line:=strings.TrimSpace(lines[i])
        if line==""||strings.HasPrefix(line,"#"){continue}
        m:=assignmentRE.FindStringSubmatch(line)
        if m==nil{return nil,fmt.Errorf("invalid line: %s",line)}
        key,value:=m[1],m[2]
        var quote byte
        if len(value)>0 && (value[0]=='\''||value[0]=='"') {quote=value[0]}
        if quote!=0 {
            // Quoted assignments can span lines. The last quote delimits a
            // value; quotes in its interior are retained verbatim.
            close:=closingQuote(value,quote)
            for close<1 && i+1<len(lines) {i++;line+="\n"+lines[i];value+="\n"+lines[i];close=closingQuote(value,quote)}
            if close<1{return nil,fmt.Errorf("unclosed quoted value in .env file")}
            tail:=strings.TrimSpace(value[close+1:])
            if tail!=""&&!strings.HasPrefix(tail,"#"){return nil,fmt.Errorf("invalid line: %s",line)}
            value=value[1:close]
            if quote=='"' {value=unescapeDotenv(value);value=os.Expand(value,lookup)}
        } else {
            if n:=strings.IndexByte(value,'#');n>=0{value=value[:n]}
            value=strings.TrimSpace(value)
            if strings.IndexFunc(value,unicode.IsSpace)>=0{return nil,fmt.Errorf("invalid line: %s",line)}
            value=os.Expand(value,lookup)
        }
        result[key]=value
    }
    return result,nil
}
func closingQuote(s string,q byte) int {
    for i:=len(s)-1;i>0;i-- {if s[i]==q {
        n:=0;for j:=i-1;j>=0&&s[j]=='\\';j--{n++}
        if n%2==0{return i}
    }}
    return -1
}
func unescapeDotenv(s string) string {
    var b strings.Builder
    for i:=0;i<len(s);i++ {
        c:=s[i]
        if c=='\\' && i+1<len(s) {
            n:=s[i+1]
            if n=='$' {b.WriteByte(c);continue}
            i++
            switch n {case 'n':b.WriteByte('\n');case 'r':b.WriteByte('\r');default:b.WriteByte(n)}
        } else {b.WriteByte(c)}
    }
    return b.String()
}
func (a *App) dotenv(args []string) error {
    shell:=at(args,0,"bash")
    path:=at(args,1,".env")
    b,err:=os.ReadFile(path);if err!=nil{return err}
    e,err:=parseDotenv(b,a.Env);if err!=nil{return err}
    if err=checkShell(shell);err!=nil{return err}
    s,err:=render(shell,fullPatch(e));if err!=nil{return err}
    fmt.Println(s);return nil
}
EOF"}

