package main

import (
    "crypto/sha256"
    "encoding/hex"
    "encoding/json"
    "fmt"
    "os"
    "path/filepath"
    "strings"
    "time"
)

type RC struct {
    Path string
    AllowPath string
    DenyPath string
    Allowed int
    Watches Watches
}
func hashString(s string) string {h:=sha256.Sum256([]byte(s));return hex.EncodeToString(h[:])}
func (a *App) newRC(path string) (*RC,error) {
    path=absolute(path)
    content,err:=os.ReadFile(path);if err!=nil{return nil,err}
    allow:=filepath.Join(a.Config.DataDir,"allow",hashString(path+"\n"+string(content)))
    deny:=filepath.Join(a.Config.DataDir,"deny",hashString(path+"\n"))
    rc:=&RC{Path:path,AllowPath:allow,DenyPath:deny,Allowed:1,Watches:Watches{}}
    rc.Watches.add(path);rc.Watches.add(allow);rc.Watches.add(deny)
    if _,err=os.Stat(deny);err==nil {rc.Allowed=2} else if _,err=os.Stat(allow);err==nil {rc.Allowed=0}
    if a.Config.Exact[path] {rc.Allowed=0}
    for _,p:=range a.Config.Prefix {if strings.HasPrefix(path,p){rc.Allowed=0;break}}
    return rc,nil
}
func (a *App) findRC(dir string) (*RC,error) {
    dir=absolute(dir)
    names:=[]string{".envrc"};if a.Config.LoadDotenv {names=append(names,".env")}
    for {
        for _,name:=range names {
            path:=filepath.Join(dir,name)
            if st,err:=os.Stat(path);err==nil && !st.IsDir() {return a.newRC(path)}
        }
        parent:=filepath.Dir(dir);if parent==dir{break};dir=parent
    }
