  log_status "using $*"
  shift
  "use_$name" "$@"
}
use_node() {
  local version="${1-}" prefix="${NODE_VERSION_PREFIX:-node-v}" root
  if [[ -z ${NODE_VERSIONS-} ]]; then log_error 'NODE_VERSIONS is not set'; return 1; fi
  if [[ ! -d $NODE_VERSIONS ]]; then log_error "NODE_VERSIONS directory $NODE_VERSIONS does not exist"; return 1; fi
  if [[ -z $version ]]; then
    watch_file .nvmrc .node-version
    if [[ -f .nvmrc ]]; then version=$(<.nvmrc); elif [[ -f .node-version ]]; then version=$(<.node-version); fi
    version=${version#v}
  fi
  root=$NODE_VERSIONS/$prefix$version
  if [[ ! -d $root ]]; then
    version=$(semver_search "$NODE_VERSIONS" "$prefix" "$version") || { log_error "Unable to find a matching NodeJS version"; return 1; }
    root=$NODE_VERSIONS/$prefix$version
  fi
  export NODE_VERSION=$version
  PATH_add "$root/bin"
}
use_julia() {
  local version="${1-}" prefix="${JULIA_VERSION_PREFIX:-julia-}" root
  if [[ -z ${JULIA_VERSIONS-} ]]; then log_error 'JULIA_VERSIONS is not set'; return 1; fi
  root=$JULIA_VERSIONS/$prefix$version
  if [[ ! -d $root ]]; then
    version=$(semver_search "$JULIA_VERSIONS" "$prefix" "$version") || return
    root=$JULIA_VERSIONS/$prefix$version
  fi
  PATH_add "$root/bin"
}
use_vim() { path_add DIRENV_EXTRA_VIMRC "${1:-.vimrc.local}"; }
use_rbenv() { eval "$(rbenv init -)"; }
use_nodenv() { eval "$(nodenv init -)"; }
use_nix() { direnv_load nix-shell "$@" --run "\"$direnv\" dump"; }
use_flake() { direnv_load nix develop "$@" --command "$direnv" dump; }
use_guix() { direnv_load guix shell "$@" -- "$direnv" dump; }
use_flox() { direnv_load flox activate -- "$direnv" dump; }
rvm() {
  local script="${rvm_path:-$HOME/.rvm}/scripts/rvm"
  if [[ -f $script ]]; then source "$script"; rvm "$@"; else log_error 'rvm not found'; return 1; fi
}

fetchurl() { "$direnv" fetchurl "$@"; }
source_url() {
  local file
  file=$(fetchurl "$@") || return
  source_env "$file"
}
direnv_apply_dump() {
  local statements
  statements=$("$direnv" apply_dump "$1") || return
  eval "$statements"
}
direnv_load() {
  local dump_file result
  dump_file=$(mktemp "${TMPDIR:-/tmp}/direnv.XXXXXXXXXX") || return
  "$@" >"$dump_file"
  result=$?
  if [[ $result == 0 ]]; then direnv_apply_dump "$dump_file"; result=$?; fi
  rm -f "$dump_file"
  return "$result"
}
require_allowed() {
  local result path="${_direnv_rc:-${BASH_SOURCE[1]}}"
  result=$("$direnv" check-required bash "$path" "$@") || return
  eval "$result"
}

__env_strictness() {
  local enabled=$1 previous=$- pipefail=0 result
  shift
  [[ $(set -o pipefail) == *on ]] && pipefail=1
  if [[ $enabled == true ]]; then set -euo pipefail; else set +e; set +u; set +o pipefail; fi
  [[ $# == 0 ]] && return 0
  "$@"
  result=$?
  if [[ $previous == *e* ]]; then set -e; else set +e; fi
  if [[ $previous == *u* ]]; then set -u; else set +u; fi
  if [[ $pipefail == 1 ]]; then set -o pipefail; else set +o pipefail; fi
  return "$result"
}
strict_env() { __env_strictness true "$@"; }
unstrict_env() { __env_strictness false "$@"; }
on_git_branch() {
  local branch="${1-}" actual head
  actual=$(git symbolic-ref --short HEAD 2>/dev/null) || return 1
  if [[ -z $branch ]]; then return 0; fi
  head=$(git rev-parse --git-path HEAD 2>/dev/null) || return 1
  watch_file "$head"
  [[ $actual == "$branch" ]]
}
__main__() {
  local source_file=$1 library
  for library in "$direnv_config_dir"/lib/*.sh; do
    if [[ -f $library ]]; then source "$library"; fi
  done
  if [[ -f $direnv_config_dir/direnvrc ]]; then source "$direnv_config_dir/direnvrc"
  elif [[ -f ${HOME-}/.direnvrc ]]; then source "$HOME/.direnvrc"
  fi
  source_env "$source_file"
}
