{"command":"cat > required.go <<'EOF'
package main

import (
    "fmt"
    "os"
    "path/filepath"
    "strings"
)

func validateRequired(path string) error {
    if filepath.IsAbs(path){return fmt.Errorf("require_allowed: path must be relative: %s",path)}
    if strings.Contains(path,".."){return fmt.Errorf("require_allowed: path must not contain '..': %s",path)}
    return nil
}
func (a *App) requiredPath(rcPath,rel string) (string,error) {
    path:=absolute(filepath.Join(filepath.Dir(rcPath),rel))
    b,err:=os.ReadFile(path);if err!=nil{return "",err}
    group:=hashString(absolute(rcPath)+"\n")
    return filepath.Join(a.Config.DataDir,"allowed-required",group,hashString(path+"\n"+string(b))),nil
}
func (a *App) authorizeRequired(rc *RC) error {
    value:=a.Env["DIRENV_REQUIRED"]
    if value==""{return nil}
    for _,path:=range strings.Split(value,":") {
        if err:=validateRequired(path);err!=nil{return err}
        marker,err:=a.requiredPath(rc.Path,path)
        if err!=nil{return fmt.Errorf("required file does not exist: %s",path)}
        if err=os.MkdirAll(filepath.Dir(marker),0755);err!=nil{return err}
        if err=os.WriteFile(marker,[]byte(path+"\n"),0644);err!=nil{return err}
        fmt.Printf("direnv: allowing %s\n",path)
    }
    return nil
}
func (a *App) checkRequired(args []string) error {
    if len(args)<1{return fmt.Errorf("a shell name is required")}
    if len(args)<2{return fmt.Errorf("an envrc path is required")}
    if len(args)<3{return fmt.Errorf("at least one file path is required")}
    shell:=args[0];if err:=checkShell(shell);err!=nil{return err}
    rcPath:=args[1]
    missing:=[]string{}
    for _,path:=range args[2:] {
        if err:=validateRequired(path);err!=nil{fmt.Printf("log_error %s;\nexit 1;\n",bashQuote(err.Error()));return nil}
        marker,err:=a.requiredPath(rcPath,path)
        if err==nil {_,err=os.Stat(marker)}
        if err!=nil {missing=append(missing,path)}
    }
    if len(missing)==0{return nil}
    out,err:=render(shell,Patch{"DIRENV_REQUIRED":pointer(strings.Join(missing,":"))});if err!=nil{return err};fmt.Print(out)
    verb:="require";if len(missing)==1{verb="requires"}
    msg:=strings.Join(missing," and ")+" "+verb+" approval. Run 'direnv allow' to approve."
    fmt.Printf("log_error %s;\nexit 0;\n",bashQuote(msg))
    return nil
}
EOF
cat > fetchurl.go <<'EOF'
package main

import (
    "crypto/sha256"
    "encoding/base64"
    "encoding/hex"
    "fmt"
    "io"
    "net/http"
    "os"
    "path/filepath"
    "strings"
    "syscall"
    "unsafe"
)

func terminal(f *os.File) bool {
    var t syscall.Termios
    _,_,e:=syscall.Syscall6(syscall.SYS_IOCTL,f.Fd(),syscall.TCGETS,uintptr(unsafe.Pointer(&t)),0,0,0)
    return e==0
}
func (a *App) fetchURL(args []string) error {
    if len(args)==0{return fmt.Errorf("missing URL argument")}
    url:=args[0];expected:=at(args,1,"")
    cas:=filepath.Join(a.cacheDirectory(),"cas")
    if expected!="" {
        algo,hash,ok:=strings.Cut(expected,"-")
        if !ok{return fmt.Errorf("sri: not a hash %s",expected)}
        if algo!="sha256"&&algo!="sha384"&&algo!="sha512"{return fmt.Errorf("sri: unsupported algo %s",algo)}
        b,err:=base64.StdEncoding.DecodeString(hash);if err!=nil{return err}
        path:=filepath.Join(cas,hex.EncodeToString(b))
        if _,err=os.Stat(path);err==nil {fmt.Println(path);return nil}
    }
    response,err:=http.Get(url);if err!=nil{return err}
    defer response.Body.Close()
    if response.StatusCode!=200{return fmt.Errorf("expected status code 200 but got %d",response.StatusCode)}
    b,err:=io.ReadAll(response.Body);if err!=nil{return err}
    sum:=sha256.Sum256(b)
    sri:="sha256-"+base64.StdEncoding.EncodeToString(sum[:])
    if expected!="" && expected!=sri{return fmt.Errorf("hash mismatch. Expected '%s' but got '%s'",expected,sri)}
    path:=filepath.Join(cas,hex.EncodeToString(sum[:]))
    if _,err=os.Stat(path);os.IsNotExist(err) {
        if err=os.MkdirAll(cas,0755);err!=nil{return err}
        temp,err:=os.CreateTemp(cas,"tmp");if err!=nil{return err}
        name:=temp.Name()
        defer func(){
            if err:=temp.Close();err!=nil{fmt.Fprintf(os.Stderr,"Warning: failed to close temp file: %s\n",err)}
            if err:=os.Remove(name);err!=nil{fmt.Fprintf(os.Stderr,"Warning: failed to remove temp file %s: %s\n",name,err)}
        }()
        if _,err=temp.Write(b);err!=nil{return err}
        if err=temp.Chmod(0500);err!=nil{return err}
        if err=temp.Close();err!=nil{return err}
        if err=os.Rename(name,path);err!=nil{return err}
    }
    if expected!="" {fmt.Println(path)} else if terminal(os.Stdout) {
        fmt.Printf("Found hash: %s\n\nInvoke fetchurl again with the hash as an argument to get the disk location:\n\n  direnv fetchurl %q %q\n",sri,url,sri)
    } else {fmt.Println(sri)}
    return nil
}
EOF
