import os,subprocess,json,sys,base64,zlib
from probe import *
NEW=ROOT+'/build/direnv'
def canonical(p,shell='raw'):
 out=p.stdout.decode(errors='replace').replace(NEW,EXE)
 err=p.stderr.decode(errors='replace').replace(NEW,EXE)
 return (p.returncode,out,err)
def pair(args,env=None,cwd=None,data=None,quiet=False,transform=None):
 e=ENV.copy();e.update(env or {})
 r=subprocess.run([EXE]+args,cwd=cwd or CWD,env=e,input=data,capture_output=True)
 n=subprocess.run([NEW]+args,cwd=cwd or CWD,env=e,input=data,capture_output=True)
 rr=canonical(r);nn=canonical(n)
