            if start==nil{return nil,fmt.Errorf("invalid line: %s",line)}
            value=line[start[2]:]
            if closingQuote(value,value[0])>0{return nil,fmt.Errorf("invalid line: %s",line)}
        }
        var quote byte
        if len(value)>0 && (value[0]=='\''||value[0]=='"') {quote=value[0]}
        if quote!=0 {
            close:=closingQuote(value,quote)
