package main

import (
    "os"
    "path/filepath"
    "reflect"
    "strings"
    "testing"
    "time"
)

func TestSerializedWatches(t *testing.T) {
    encoded, err := marshal(Watches{})
    if err != nil { t.Fatal(err) }
    if encoded != "eJyKjgUEAAD__wEVALk=" { t.Fatalf("unexpected empty watch representation: %s", encoded) }
    input := Diff{Prev: Env{"OLD":"value"}, Next: Env{"NEW":"a\nb", "EMPTY":""}}
    encoded, err = marshal(input)
    if err != nil { t.Fatal(err) }
    var output Diff
    if err = unmarshal(encoded, &output); err != nil { t.Fatal(err) }
    if !reflect.DeepEqual(input, output) { t.Fatalf("round trip: %#v", output) }
}

func TestDotenvParsing(t *testing.T) {
    base:=Env{"HOME":"/home/test", "EMPTY":""}
    tests:=[]struct{input string; want Env}{
        {"A=one\nB=$A-two\nC=${EMPTY:-default}\nD='$HOME'\n", Env{"A":"one","B":"one-two","C":"default","D":"$HOME"}},
        {"export A=foo#comment\n B = \"a\\nb\\tc\"\nC: value\n",Env{"A":"foo","B":"a\nbtc","C":"value"}},
        {"A='x\ny'\nB=\"x\\\ny\"\n",Env{"A":"x\ny","B":"x\ny"}},
        {"A=\"foo\\\"\n",Env{"A":"foo\\"}},
        {"A-='x\ny'\n",Env{}},
        {"A: \nA.B=2\n",Env{"A":"","A.B":"2"}},
    }
    for _,tc:=range tests {
        got,err:=parseDotenv([]byte(tc.input),base)
        if err!=nil {t.Fatalf("%q: %v",tc.input,err)}
        if !reflect.DeepEqual(got,tc.want) {t.Errorf("%q: got %#v want %#v",tc.input,got,tc.want)}
    }
    for _,input:=range []string{"A : value\n"," A = two words \n", "A=\"x\ny\" #comment\n"} {
        if _,err:=parseDotenv([]byte(input),base);err==nil {t.Errorf("accepted invalid input %q",input)}
    }
    if _,err:=parseDotenv([]byte("  invalid line  \n"),base);err==nil||err.Error()!="invalid line:   invalid line  " {t.Fatalf("error did not retain the original line: %v",err)}
}

func TestEnvironmentDifference(t *testing.T) {
    old:=Env{"A":"old","PATH":"/bin","PWD":"/old","DIRENV_CONFIG":"/config"}
    next:=Env{"A":"new","B":"added","PWD":"/new","DIRENV_CONFIG":"/other"}
    diff:=difference(old,next)
    if !reflect.DeepEqual(diff.Prev,Env{"A":"old","PATH":"/bin"}) {t.Fatal(diff)}
    if !reflect.DeepEqual(diff.Next,Env{"A":"new","B":"added"}) {t.Fatal(diff)}
    reverted:=diff.reverse(next)
    if reverted["A"]!="old"||reverted["PATH"]!="/bin"||reverted["PWD"]!="/new" {t.Fatal(reverted)}
    if _,ok:=reverted["B"];ok {t.Fatal("addition was not removed")}
}

func TestShellFormats(t *testing.T) {
    cases:=[]struct{shell string; patch Patch; want string}{
        {"bash",Patch{"A":pointer("hello")},"export A=$'hello';"},
        {"bash",Patch{"A":pointer("ABC-1")},"export A=ABC-1;"},
        {"bash",Patch{"A":pointer("é\n")},"export A=$'\\xc3\\xa9\\n';"},
        {"fish",Patch{"PATH":pointer("/a::/b")},"set -x -g PATH '/a' '' '/b';"},
        {"pwsh",Patch{"A":pointer("it's")},"${env:A}='it''s';"},
        {"vim",Patch{"A":nil},"call setenv('A',v:null)\n"},
        {"systemd",Patch{"A":nil},""},
        {"json",Patch{"A":pointer("<&>")},"{\n  \"A\": \"\\u003c\\u0026\\u003e\"\n}"},
    }
    for _,tc:=range cases {
        text,err:=render(tc.shell,tc.patch)
        if err!=nil||text!=tc.want {t.Errorf("%s: got %q (%v), want %q",tc.shell,text,err,tc.want)}
    }
}

func TestFileWatches(t *testing.T) {
    file:=filepath.Join(t.TempDir(),"watch")
    missing:=fileWatch(file)
    if missing.Exists||missing.current()!=nil {t.Fatal(missing)}
    if err:=os.WriteFile(file,[]byte("x"),0644);err!=nil {t.Fatal(err)}
    if err:=missing.current();err==nil||!strings.Contains(err.Error(),"newly created") {t.Fatal(err)}
    stamp:=time.Unix(1700000000,123)
    if err:=os.Chtimes(file,stamp,stamp);err!=nil {t.Fatal(err)}
    watch:=fileWatch(file)
    if watch.Modtime!=1700000000||watch.current()!=nil {t.Fatal(watch)}
    next:=stamp.Add(time.Second)
    if err:=os.Chtimes(file,next,next);err!=nil {t.Fatal(err)}
    if watch.current()==nil {t.Fatal("failed to detect a modification")}
}
