#!/usr/bin/env python3
"""Self-contained end-to-end checks; no third-party packages are needed."""
import base64
import hashlib
import http.server
import json
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import threading
import unittest
import zlib

EXECUTABLE = str(Path(sys.argv.pop(1) if len(sys.argv) > 1 else './executable').resolve())


class IntegrationTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        for name in ('home', 'config', 'data', 'cache', 'project', 'outside'):
            (self.root / name).mkdir()
        self.env = {
            'HOME': str(self.root / 'home'),
            'PATH': '/usr/bin:/bin',
            'XDG_CONFIG_HOME': str(self.root / 'config'),
            'XDG_DATA_HOME': str(self.root / 'data'),
            'XDG_CACHE_HOME': str(self.root / 'cache'),
        }
        self.project = self.root / 'project'

    def tearDown(self):
        self.temp.cleanup()

    def run_command(self, *args, cwd=None, env=None, code=0):
        current = self.env.copy()
        current.update(env or {})
        p = subprocess.run([EXECUTABLE, *args], cwd=cwd or self.project,
                           env=current, capture_output=True, text=True)
        self.assertEqual(p.returncode, code, p.stderr)
        return p

    @staticmethod
    def apply(env, patch):
        result = env.copy()
        for key, value in patch.items():
            if value is None:
                result.pop(key, None)
            else:
                result[key] = value
        return result

    def test_load_and_unload(self):
        self.assertEqual(self.run_command('version').stdout, '2.37.1\n')
        rc = self.project / '.envrc'
        rc.write_text('export FOO=hello\nunset OLD\nPATH_add bin\ndotenv_if_exists .env.local\n')
        blocked = self.run_command('export', 'json', code=1)
        self.assertIn('is blocked', blocked.stderr)
        self.run_command('allow')
        p = self.run_command('export', 'json', env={'OLD': 'old'})
        patch = json.loads(p.stdout)
        self.assertEqual(patch['FOO'], 'hello')
        self.assertIsNone(patch['OLD'])
        self.assertEqual(patch['PATH'], str(self.project / 'bin') + ':/usr/bin:/bin')
        watches = json.loads(zlib.decompress(base64.urlsafe_b64decode(patch['DIRENV_WATCHES'])))
        self.assertEqual(watches[-1]['path'], str(self.project / '.env.local'))
        self.assertFalse(watches[-1]['exists'])
        loaded = self.apply(dict(self.env, OLD='old'), patch)
        self.assertEqual(self.run_command('export', 'json', env=loaded).stdout, '')
